cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void matmul_fp16_kernel(const __half* __restrict__ A,
                                   const __half* __restrict__ B,
                                   __half* __restrict__ C,
                                   int M, int K, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= M || col >= N) return;
    float sum = 0.0f;
    for (int k = 0; k < K; ++k) {
        float a = __half2float(A[row * K + k]);
        float b = __half2float(B[k * N + col]);
        sum += a * b;
    }
    C[row * N + col] = __float2half(sum);
}

void matmul_fp16(torch::Tensor A, torch::Tensor B, torch::Tensor C) {
    TORCH_CHECK(A.dtype() == torch::kHalf, "A must be half precision");
    TORCH_CHECK(B.dtype() == torch::kHalf, "B must be half precision");
    TORCH_CHECK(C.dtype() == torch::kHalf, "C must be half precision");
    TORCH_CHECK(A.is_cuda() && B.is_cuda() && C.is_cuda(),
                "All tensors must be on CUDA device");

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    const dim3 block(16, 16);
    const dim3 grid((N + block.x - 1) / block.x,
                    (M + block.y - 1) / block.y);

    matmul_fp16_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(A.data_ptr()),
        reinterpret_cast<const __half*>(B.data_ptr()),
        reinterpret_cast<__half*>(C.data_ptr()),
        M, K, N);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16, "Half‑precision matrix multiplication (CUDA)");
}
'''

# Compile the extension in‑line
matmul_ext = load_inline(
    name="matmul_fp16_ext",
    cpp_sources="",
    cuda_sources=cuda_source,
    functions=["matmul_fp16"],
    verbose=False,
)

def matmul_fp16(A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
    """Wrapper that allocates output and calls the CUDA kernel."""
    assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
    assert A.dtype == torch.float16 and B.dtype == torch.float16, "Inputs must be fp16"
    M, K = A.shape
    K2, N = B.shape
    assert K == K2, "Incompatible shapes for matmul"
    C = torch.empty((M, N), device=A.device, dtype=A.dtype)
    matmul_ext.matmul_fp16(A, B, C)
    return C

